9	 * the upper-cased first three letters of the owner's last name and NNNN is a global
10	 * 4-digit zero-padded sequence equal to one more than the current number of owners
11	 * (e.g. {@code 'SMI-0007'}). Runs after {@link BuildOwner} (the entity, hence its last
12	 * name, exists) and before {@link SaveOwner} (so the new owner is not yet counted), and
13	 * mutates the built {@link Owner} in place.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String lastName = owner.getLastName();
19	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
20	        int sequence = ownerRepository.findAll().size() + 1;
21	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
22	    }
23	}
