3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'}:
8	 * customerCode is the value assigned by {@link AssignCustomerCode} and YY is the last two
9	 * digits of the owner's {@code registrationDate} year, zero-padded (e.g.
10	 * {@code 'SMI-0007-M26'}). Runs after {@link AssignCustomerCode} (so customerCode exists)
11	 * and mutates the built {@link Owner} in place.
12	 */
13	public class AssignMembershipNumber {
14	
15	    public void service(@Val Owner owner) {
16	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
17	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
18	    }
19	}
